GRANT SELECT ON platform.schema_migrations,platform.outbox_events TO langtutor_authenticator;
CREATE OR REPLACE FUNCTION operations.record_system_event(p_severity text,p_code text,p_request_id uuid) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,operations AS $$BEGIN IF p_severity NOT IN('info','warning','error','critical') OR p_code!~'^[A-Z0-9_.-]{3,80}$' THEN RAISE EXCEPTION 'INVALID_SYSTEM_EVENT' USING ERRCODE='P0001';END IF;INSERT INTO operations.system_events(id,severity,code,request_id)VALUES(gen_random_uuid(),p_severity,p_code,p_request_id);END$$;
REVOKE ALL ON FUNCTION operations.record_system_event(text,text,uuid) FROM PUBLIC;ALTER FUNCTION operations.record_system_event(text,text,uuid) OWNER TO langtutor_authenticator;GRANT EXECUTE ON FUNCTION operations.record_system_event(text,text,uuid) TO langtutor_runtime;

CREATE OR REPLACE FUNCTION admin.system_status(p_token_hash text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,admin,platform,operations AS $$DECLARE v_actor uuid;v_result jsonb;BEGIN v_actor:=admin.require_session(p_token_hash,false);SELECT jsonb_build_object('migrations',coalesce((SELECT jsonb_agg(jsonb_build_object('name',name,'appliedAt',applied_at) ORDER BY name)FROM platform.schema_migrations),'[]'::jsonb),'pendingEmailJobs',(SELECT count(*) FROM platform.outbox_events WHERE processed_at IS NULL),'systemErrors24h',(SELECT count(*) FROM operations.system_events WHERE severity IN('error','critical') AND created_at>now()-interval '24 hours'))INTO v_result;RETURN v_result;END$$;
REVOKE ALL ON FUNCTION admin.system_status(text) FROM PUBLIC;ALTER FUNCTION admin.system_status(text) OWNER TO langtutor_authenticator;GRANT EXECUTE ON FUNCTION admin.system_status(text) TO langtutor_runtime;
